import { useEffect, useRef } from 'react'
import * as echarts from 'echarts/core'
import { BarChart, LineChart } from 'echarts/charts'
import { GridComponent, LegendComponent, TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'

echarts.use([BarChart, LineChart, GridComponent, TooltipComponent, LegendComponent, CanvasRenderer])

type Row = { month: string; revenue: number; target: number }

export function Revenue({ rows }: { rows: Row[] }) {
  const el = useRef<HTMLDivElement>(null)
  const chart = useRef<echarts.ECharts | null>(null)

  useEffect(() => {
    const instance = echarts.init(el.current!)
    chart.current = instance
    const onResize = () => instance.resize()
    window.addEventListener('resize', onResize)
    return () => {
      window.removeEventListener('resize', onResize)
      instance.dispose()
    }
  }, [])

  useEffect(() => {
    chart.current?.setOption({
      xAxis: { type: 'category', data: rows.map((r) => r.month) },
      yAxis: { type: 'value', axisLabel: { formatter: (v: number) => `$${v}` } },
      tooltip: { trigger: 'axis' },
      legend: {},
      series: [
        { type: 'bar', name: 'Revenue', data: rows.map((r) => r.revenue) },
        { type: 'line', name: 'Target', data: rows.map((r) => r.target) },
      ],
    })
  }, [rows])

  return <div ref={el} style={{ height: 320 }} />
}

