export function mountVisitors(canvas: HTMLCanvasElement, days: Day[]) {
  const chart = new Chart(canvas, {
    type: 'line',
    data: {
      labels: days.map((d) => d.day),
      datasets: [{ label: 'Visitors', data: days.map((d) => d.visitors), tension: 0.3 }],
    },
    options: {
      scales: { y: { ticks: { callback: (v) => `${Number(v) / 1000}k` } } },
    },
  })

  // When the data changes, copy it back in and ask for a redraw.
  return function load(next: Day[]) {
    chart.data.labels = next.map((d) => d.day)
    chart.data.datasets[0]!.data = next.map((d) => d.visitors)
    chart.update()
  }
}

