import { Axis, Chart, Legend, Line, Tooltip, compact, smooth } from '@pyreon/charts'
import { signal } from '@pyreon/reactivity'

type Day = { day: string; visitors: number }
export const visits = signal<Day[]>([])

export const Visitors = () => (
  <Chart data={visits} x="day" height={280}>
    <Line y="visitors" label="Visitors" curve={smooth} />
    <Axis y format={compact} />
    <Tooltip />
    <Legend />
  </Chart>
)

// When the data changes, write the signal. The canvas repaints in place.
export function load(next: Day[]) {
  visits.set(next)
}

