import { onMount } from '@pyreon/core'
import { Chart, Line, Tooltip } from '@pyreon/charts'
import { signal } from '@pyreon/reactivity'

type Tick = { t: number; label: string; latency: number }

export const LiveLatency = (props: { read: () => number }) => {
  const ticks = signal<Tick[]>([])
  onMount(() => {
    let t = 0
    const id = setInterval(() => {
      t += 1
      const next = { t, label: `${t}s`, latency: props.read() }
      ticks.update((rows) => [...rows.slice(-59), next])
    }, 1000)
    return () => clearInterval(id)
  })
  return (
    <Chart data={ticks} x="label" by="t" height={200} title="Latency, last 60 s">
      <Line y="latency" label="Latency (ms)" />
      <Tooltip />
    </Chart>
  )
}

import { Bar, Chart, Line, Tooltip, Zoom, createChartLink } from '@pyreon/charts'

type Day = { day: string; close: number; volume: number }

export const PriceAndVolume = (props: { days: Day[] }) => {
  const link = createChartLink()
  return (
    <>
      <Chart<Day> data={props.days} x="day" height={240}>
        <Line y="close" label="Close" />
        <Tooltip crosshair />
        <Zoom inside navigator link={link} presets={[{ label: '1M', count: 21 }, { label: 'All', count: 0 }]} />
      </Chart>
      <Chart<Day> data={props.days} x="day" height={120}>
        <Bar y="volume" label="Volume" />
        <Tooltip crosshair />
        <Zoom inside link={link} />
      </Chart>
    </>
  )
}
